def two(rh, lh, key='C', meter='4/4'):
    """A melody over a bass (right and left hand), as ABC."""
    return (f'X:1\n%%stretchlast 1\n%%annotationfont Inter 14\n%%staves {{RH LH}}\nM:{meter}\nL:1/4\nK:{key}\n'
            f'V:RH clef=treble\nV:LH clef=bass\n[V:RH] {rh}\n[V:LH] {lh}\n')


def q_enharmonic(pitch, answer, others):
    return ask(L('Which note sounds the same as {N:%s}?' % pitch, 'Welcher Ton klingt gleich wie {N:%s}?' % pitch, 'Quelle note sonne comme {N:%s} ?' % pitch),
               ['{N:%s}' % answer] + ['{N:%s}' % o for o in others])


