NCT = [('P', L('passing note', 'Durchgangston', 'note de passage')), ('N', L('neighbour note', 'Wechselnote (Nebennote)', 'broderie')),
       ('S', L('suspension', 'Vorhalt', 'retard')), ('A', L('appoggiatura', 'Appoggiatur (freier Vorhalt)', 'appoggiature')), ('Ant', L('anticipation', 'Antizipation (Vorausnahme)', 'anticipation'))]
NCT_NAMES = dict(NCT)


def cap(text):
    return text[:1].upper() + text[1:]


def q_nct(kind, rh, lh, meter='4/4'):
    others = [n for k, n in NCT if k != kind][:3]
    return ask(L('What is the marked note (*)?', 'Was ist die markierte Note (*)?', 'Quelle est la note marquée (*) ?'), [NCT_NAMES[kind]] + others, music=two(rh, lh, meter=meter))


