# --- Month 11 ------------------------------------------------------------------


def figured(bass, figures, key='C', meter='none'):
    """A bass line with figures underneath (figured bass)."""
    body = ' '.join((f'"_{f}"' if f else '') + abc_pitch(p, key) + '2' for p, f in zip(bass, figures))
    return f'X:1\n%%stretchlast 1\n%%annotationfont Inter 18\nM:{meter}\nL:1/4\nK:{key} clef=bass\n{body} |]\n'


def q_figure(bass, figure, answer, others, key='C'):
    return ask(L('Which chord does this figured bass note stand for?', 'Für welchen Akkord steht diese bezifferte Bassnote?', 'Quel accord représente cette basse chiffrée ?'),
               [answer] + others, music=figured([bass], [figure], key))


def tn(root, kind='major', inv=None):
    """Triad name option, with optional inversion label."""
    labels = {1: L('1st inversion', 'Sextakkord', '1er renversement'), 2: L('2nd inversion', 'Quartsextakkord', '2e renversement')}
    return lambda lang: triad_name(root, kind, lang) + (f" ({localize(labels[inv], lang)})" if inv else '')


